#!/usr/bin/env node
// Refresh Codex OAuth token and push to GitHub secret preloopdev/preloop:CODEX_AUTH_JSON
// Mirrors pullfrog/utils/codexOAuth.ts:refreshCodexAuthBody
import { readFileSync, writeFileSync } from "node:fs";
import { execSync } from "node:child_process";

const AUTH_PATH = `${process.env.HOME}/.codex/auth.json`;
const REPO = "preloopdev/preloop";
const SECRET_NAME = "CODEX_AUTH_JSON";
const CLIENT_ID = "app_EMoamEEZ73f0CkXaXp7hrann";
const TOKEN_URL = "https://auth.openai.com/oauth/token";

function loadAuth() {
  const raw = readFileSync(AUTH_PATH, "utf8");
  return JSON.parse(raw);
}

async function refresh(body) {
  const res = await fetch(TOKEN_URL, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type: "refresh_token",
      refresh_token: body.tokens.refresh_token,
      client_id: CLIENT_ID,
    }).toString(),
    signal: AbortSignal.timeout(10_000),
  });
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`refresh failed ${res.status} ${text}`);
  }
  const tok = await res.json();
  return {
    auth_mode: "chatgpt",
    tokens: {
      access_token: tok.access_token,
      refresh_token: tok.refresh_token,
      ...(tok.id_token ?? body.tokens.id_token ? { id_token: tok.id_token ?? body.tokens.id_token } : {}),
      ...(body.tokens.account_id ? { account_id: body.tokens.account_id } : {}),
    },
    last_refresh: new Date().toISOString(),
  };
}

async function main() {
  const before = loadAuth();
  console.log(`[codex-refresh] refreshing ${AUTH_PATH} last_refresh=${before.last_refresh}`);
  const after = await refresh(before);
  // atomic write
  writeFileSync(AUTH_PATH, JSON.stringify(after, null, 2) + "\n");
  console.log(`[codex-refresh] wrote new tokens, new refresh truncated=${after.tokens.refresh_token.slice(0,20)}...`);

  // push to GitHub secret via gh
  const jsonStr = JSON.stringify(after);
  // gh secret set reads from stdin; use exec
  try {
    execSync(`gh secret set ${SECRET_NAME} --repo ${REPO} --body '${jsonStr.replace(/'/g, "'\\''")}'`, { stdio: "inherit" });
    console.log(`[codex-refresh] gh secret set ${SECRET_NAME} done`);
  } catch (e) {
    console.error(`[codex-refresh] gh secret set failed: ${e.message}`);
    // still succeed locally; GH secret will be stale until next manual run
    process.exitCode = 1;
  }
}

main().catch(e => {
  console.error(`[codex-refresh] fatal: ${e.stack || e.message}`);
  if (String(e.message).includes("400") || String(e.message).includes("invalid_grant")) {
    console.error(`[codex-refresh] refresh_token rejected — re-run: codex login --device-auth  &&  gh secret set CODEX_AUTH_JSON --repo ${REPO} < ~/.codex/auth.json`);
  }
  process.exit(1);
});

